def predict_hydrology_proba(sequence_array):
    """
    Predict hydrology probabilities from a prebuilt 3D sequence array.

    Expected shape:
        (n_samples, seq_len, n_features)
    """
    spec = load_subsystem_spec("hydrology")
    model = load_runtime_model("hydrology")

    expected_seq_len = spec.sequence_config["seq_len"]
    expected_feat_count = len(spec.feature_list)

    if len(sequence_array.shape) != 3:
        raise ValueError(
            f"hydrology: expected 3D array (n, seq_len, feat), got shape {sequence_array.shape}"
        )

    if sequence_array.shape[1] != expected_seq_len:
        raise ValueError(
            f"hydrology: expected seq_len={expected_seq_len}, got {sequence_array.shape[1]}"
        )

    if sequence_array.shape[2] != expected_feat_count:
        raise ValueError(
            f"hydrology: expected feature count={expected_feat_count}, got {sequence_array.shape[2]}"
        )

    proba = model.predict(sequence_array, verbose=0)
    cols = [f"p{i}" for i in range(proba.shape[1])]
    return pd.DataFrame(proba, columns=cols)
